E("atal-pension-yojana", name="Atal Pension Yojana (APY)", short="A fixed pension of ₹1,000 to ₹5,000 a month after age 60.", tag="Pension", ministry="Ministry of Finance / PFRDA",
 facts=[("Monthly pension","₹1,000 to ₹5,000 (after 60)"),("Age","18 to 40 years"),("Contribution","Depends on age and chosen pension"),("Bank account","Savings account required")],
 about="Atal Pension Yojana is for unorganised sector workers. You join between 18 and 40, pay a fixed monthly contribution based on your age and chosen pension, and after 60 receive ₹1,000 to ₹5,000 a month.",
 benefits=["Fixed monthly pension after 60 (choose from ₹1,000, 2,000, 3,000, 4,000 or 5,000)","On the holder's death, the spouse gets the same pension, and after both the nominee gets the corpus","The younger you join, the lower the monthly contribution"],
 elig=["Age 18 to 40 years","Savings bank/post office account and Aadhaar","Valid mobile number"],
 notelig=["Income taxpayers cannot make new applications from 1 October 2022","New applicants above 40 years"],
 docs=["Aadhaar card","Savings account","Mobile number","Nominee details"],
 steps=["Take the APY form from your bank branch/post office, net banking or app","Choose the pension amount you want (₹1,000 to ₹5,000)","Consent to auto-debit from the bank account","Add a nominee and make sure the monthly contribution keeps getting deposited"],
 link_label="jansuraksha.gov.in – Jan Suraksha portal", helpline="",
 faq=[("How much will the monthly contribution be?","It depends on your age and chosen pension. Ask the bank for the APY chart to get the exact amount for your age."),("Can income taxpayers join?","From 1 October 2022 income taxpayers cannot open new accounts."),("What if I must stop contributing midway?","Penalty can apply for missed contributions and the account may be closed after a long gap. Ask the bank the rules.")],
 note="PFRDA/government can change the contribution chart and rules. Ask the bank for the latest chart before joining.")
E("kisan-credit-card", name="Kisan Credit Card (KCC)", short="Cheap and timely credit for farmers for cultivation.", tag="Farm loan", ministry="Ministry of Agriculture / Banks",
 facts=[("Purpose","Credit for farming, crops and related expenses"),("Interest relief","Interest subvention on timely repayment (as per bank)"),("Where from","Banks, Gramin banks, cooperative banks"),("Portal","Bank branch / information on PM Kisan portal")],
 about="The Kisan Credit Card scheme gives farmers easy and cheap credit for needs like seeds, fertiliser and pesticides. On timely repayment there is a government interest concession. Farmers engaged in animal husbandry and fisheries are also covered.",
 benefits=["Flexible credit for farm expenses","Interest concession on timely repayment (as per applicable scheme)","Easier to link with crop insurance","Cards also available for animal husbandry and fisheries"],
 elig=["Farmers who cultivate (landowners or tenants, as per bank rules)","Farmers in animal husbandry and fisheries","Self-help groups / joint liability groups (as per bank rules)"],
 notelig=["Those who are defaulters on earlier agricultural loans (as per bank conditions)"],
 docs=["Aadhaar card","Land papers / proof of cultivation","Passport-size photo","Bank account details","Other papers asked by the bank"],
 steps=["Ask about KCC at your bank/cooperative bank branch","Fill the application form and submit land and ID documents","The bank checks and fixes the limit","After the card is issued, use it as needed and repay on time"],
 link_label="pmkisan.gov.in – farmer portal", helpline="",
 faq=[("How much loan does KCC give?","The limit depends on your land, crop and the bank's assessment. The government has announced higher interest-subvention limits in recent years, so ask the bank for the latest limit."),("What interest rate is charged?","With timely repayment there is a government concession, so the effective rate is much lower. Ask the bank for the exact rate."),("Can PM Kisan beneficiaries get a KCC?","Yes, many banks keep the KCC process easy for PM Kisan beneficiaries. Ask your branch.")],
 note="The government changes interest subvention and loan limits from time to time. Confirm final terms in writing with the bank.")
